import{_ as n,o as e,c as a,a1 as l}from"./chunks/framework.Ccs17H5l.js";const o="data:image/svg+xml,%3c?xml%20version='1.0'%20encoding='UTF-8'?%3e%3csvg%20width='64'%20height='64'%20xmlns='http://www.w3.org/2000/svg'%3e%3crect%20width='64'%20height='64'%20fill='rgb(66,138,245)'%20/%3e%3c/svg%3e",p="data:image/svg+xml,%3csvg%20width='64'%20height='64'%20xmlns='http://www.w3.org/2000/svg'%3e%3crect%20width='64'%20height='64'%20fill='rgb(66,136,248)'%20/%3e%3c/svg%3e",y=JSON.parse('{"title":"Le RGB 565","description":"","frontmatter":{},"headers":[],"relativePath":"old-docs/TECHNICALS/EIF/RGB565.md","filePath":"old-docs/TECHNICALS/EIF/RGB565.md"}'),r={name:"old-docs/TECHNICALS/EIF/RGB565.md"};function t(c,s,i,u,D,b){return e(),a("div",null,[...s[0]||(s[0]=[l(`<h1 id="le-rgb-565" tabindex="-1">Le RGB 565 <a class="header-anchor" href="#le-rgb-565" aria-label="Permalink to &quot;Le RGB 565&quot;">​</a></h1><blockquote><p>Le format RGB 565 est un format de couleur sur 16 bits, utilisé principalement dans les systèmes embarqués et les écrans à mémoire limitée. Cette page explique son fonctionnement, ses avantages et comment convertir depuis et vers le RGB 888.</p></blockquote><h2 id="differenciation" tabindex="-1">Différenciation <a class="header-anchor" href="#differenciation" aria-label="Permalink to &quot;Différenciation&quot;">​</a></h2><p>Lorsqu&#39;on parle de RGB, sans précision, on fait généralement référence au format RGB 888. Mais alors, qu&#39;est-ce que le RGB 888 ?</p><p>Le RGB 888, c&#39;est le fameux format de couleur où l&#39;on représente la couleur grâce au Rouge, Vert et Bleu, chacun quantifié de 0 à 255.</p><p>Exemple avec du CSS :</p><div class="language-css line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span style="color:#569CD6;">background-color</span><span style="color:#D4D4D4;">: rgb(255, 0, 0); </span><span style="color:#6A9955;">/* Rouge */</span></span>
<span class="line"><span style="color:#569CD6;">background-color</span><span style="color:#D4D4D4;">: rgb(0, 255, 0); </span><span style="color:#6A9955;">/* Vert */</span></span>
<span class="line"><span style="color:#569CD6;">background-color</span><span style="color:#D4D4D4;">: rgb(0, 0, 255); </span><span style="color:#6A9955;">/* Bleu */</span></span>
<span class="line"><span style="color:#569CD6;">background-color</span><span style="color:#D4D4D4;">: rgb(255, 255, 0); </span><span style="color:#6A9955;">/* Jaune */</span></span>
<span class="line"><span style="color:#569CD6;">background-color</span><span style="color:#D4D4D4;">: rgb(0, 255, 255); </span><span style="color:#6A9955;">/* Cyan */</span></span>
<span class="line"><span style="color:#569CD6;">background-color</span><span style="color:#D4D4D4;">: rgb(255, 0, 255); </span><span style="color:#6A9955;">/* Magenta */</span></span>
<span class="line"><span style="color:#569CD6;">background-color</span><span style="color:#D4D4D4;">: rgb(255, 255, 255); </span><span style="color:#6A9955;">/* Blanc */</span></span>
<span class="line"><span style="color:#569CD6;">background-color</span><span style="color:#D4D4D4;">: rgb(0, 0, 0); </span><span style="color:#6A9955;">/* Noir */</span></span>
<span class="line"><span style="color:#D4D4D4;">etc...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>Le RGB normal (donc le RGB 888) a donc un total de <code>256 x 256 x 256 = 16 777 216</code> couleurs possibles.</p><h3 id="pourquoi-le-888" tabindex="-1">Pourquoi le 888 ? <a class="header-anchor" href="#pourquoi-le-888" aria-label="Permalink to &quot;Pourquoi le 888 ?&quot;">​</a></h3><p>Le RGB 888 signifie que chacune des trois couleurs (Rouge, Vert, Bleu) est encodée en binaire sur 8 bits (1 octet), soit <code>2^8 = 256</code> valeurs possibles (de 0 à 255).</p><p>Chaque couleur utilise donc 8 bits, d&#39;où le nom RGB 888 (8 bits pour le Rouge, 8 bits pour le Vert, 8 bits pour le Bleu). Ce qui fait un total de <code>8 + 8 + 8 = 24 bits</code> par pixel, soit 3 octets par pixel.</p><h2 id="rgb-565" tabindex="-1">RGB 565 <a class="header-anchor" href="#rgb-565" aria-label="Permalink to &quot;RGB 565&quot;">​</a></h2><p>Comme on l&#39;a vu, le RGB 888 utilise <strong>8 bits par couleur</strong>. Le RGB 565, c&#39;est le même principe, mais avec une répartition <strong>différente</strong> des bits.</p><p>En premier lieu, <strong>5</strong> bits pour encoder le Rouge en binaire, <strong>6</strong> bits pour le Vert, et <strong>5</strong> bits pour le Bleu. On a donc <code>2^5 = 32</code> valeurs possibles pour le Rouge et le Bleu, et <code>2^6 = 64</code> valeurs possibles pour le Vert. Soit un total de <code>32 x 64 x 32 = 65 536</code> couleurs possibles.</p><h2 id="avantages-et-inconvenients" tabindex="-1">Avantages et inconvénients <a class="header-anchor" href="#avantages-et-inconvenients" aria-label="Permalink to &quot;Avantages et inconvénients&quot;">​</a></h2><p>Vous allez me dire : &quot;Mais 65 536 couleurs, c&#39;est rien du tout comparé aux 16 millions de couleurs du RGB 888 !&quot;. Et OUI, c&#39;est vrai, mais pour beaucoup de cas d&#39;utilisation, avoir moins de profondeur de couleur est acceptable, surtout quand on compare avec l&#39;énorme avantage du RGB 565. Vous allez comprendre.</p><p>Le RGB 565 utilise donc <code>5 bits + 6 bits + 5 bits = 16 bits</code> par pixel, soit <strong>2 octets</strong> par pixel. Le RGB 888, lui, utilise <strong>24 bits</strong> par pixel, soit <strong>3 octets</strong> par pixel.</p><p>UN octet de différence par pixel ! Alors oui, pour des ordinateurs avec 8, 16, 32 Go de RAM, 1 octet de plus ou de moins, c&#39;est rien. Mais sur des systèmes embarqués, qui ont 256 Mo, 512 Mo, ou même 256 Ko de RAM (comme dans notre cas, avec la Numworks), chaque octet compte !</p><p>Faisons un petit calcul rapide :</p><div class="language-bat line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span style="color:#D4D4D4;">La calculatrice Numworks a un écran de 320x240 pixels.</span></span>
<span class="line"><span style="color:#B5CEA8;">320</span><span style="color:#D4D4D4;"> x </span><span style="color:#B5CEA8;">240</span><span style="color:#D4D4D4;"> = </span><span style="color:#B5CEA8;">76</span><span style="color:#B5CEA8;"> 800</span><span style="color:#D4D4D4;"> pixels</span></span>
<span class="line"><span style="color:#D4D4D4;">En RGB </span><span style="color:#B5CEA8;">888</span><span style="color:#D4D4D4;"> : </span><span style="color:#B5CEA8;">76</span><span style="color:#B5CEA8;"> 800</span><span style="color:#D4D4D4;"> pixels x </span><span style="color:#B5CEA8;">3</span><span style="color:#D4D4D4;"> octets = </span><span style="color:#B5CEA8;">230</span><span style="color:#B5CEA8;"> 400</span><span style="color:#D4D4D4;"> octets (~225 Ko)</span></span>
<span class="line"><span style="color:#D4D4D4;">En RGB </span><span style="color:#B5CEA8;">565</span><span style="color:#D4D4D4;"> : </span><span style="color:#B5CEA8;">76</span><span style="color:#B5CEA8;"> 800</span><span style="color:#D4D4D4;"> pixels x </span><span style="color:#B5CEA8;">2</span><span style="color:#D4D4D4;"> octets = </span><span style="color:#B5CEA8;">153</span><span style="color:#B5CEA8;"> 600</span><span style="color:#D4D4D4;"> octets (~150 Ko)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#D4D4D4;">Soit une différence de </span><span style="color:#B5CEA8;">76</span><span style="color:#B5CEA8;"> 800</span><span style="color:#D4D4D4;"> octets (~75 Ko).</span></span>
<span class="line"><span style="color:#D4D4D4;">Ce qui correspond à environ 30% de RAM en moins utilisée !</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><blockquote><p>Alors oui, les connaisseurs en électronique embarquée diront qu&#39;effectivement, ce n&#39;est pas véritablement la RAM de la calculatrice qui est impactée, mais plutôt la VRAM (Video RAM) de l&#39;écran lui-même (uniquement dédiée à l&#39;affichage). Mais le principe reste le même : moins on utilise de mémoire, mieux c&#39;est. Et puis, cela rend aussi les écrans moins chers !</p></blockquote><h2 id="pourquoi-5-6-5-bits" tabindex="-1">Pourquoi 5, 6, 5 bits ? <a class="header-anchor" href="#pourquoi-5-6-5-bits" aria-label="Permalink to &quot;Pourquoi 5, 6, 5 bits ?&quot;">​</a></h2><p>Pourquoi pas 555 ou 666 bits alors ?</p><p>Vous l&#39;aurez remarqué, <code>5 + 6 + 5 = 16 bits</code>, ce qui fait un total rond et compact de 2 octets par pixel. Et c&#39;est bien plus pratique de stocker des choses sur des octets entiers. Sinon il faudrait faire du bit-packing, et c&#39;est plus compliqué à gérer et plus de calculs à faire.</p><p>Donc pourquoi c&#39;est le <strong>vert</strong> qui a <strong>6 bits</strong> et pas le rouge ou le bleu ? Car l&#39;œil humain est plus sensible au vert qu&#39;aux autres couleurs. Donc vu qu&#39;on a moins de profondeur de couleur, on privilégie la couleur la plus importante pour l&#39;œil humain. Ça permet d&#39;avoir un meilleur rendu visuel, déjà qu&#39;on a moins de couleurs, autant les rendre moins ternes que possible !</p><h3 id="exemple" tabindex="-1">Exemple : <a class="header-anchor" href="#exemple" aria-label="Permalink to &quot;Exemple :&quot;">​</a></h3><p>En RGB 888 <code>(66/255, 138/255, 245/255)</code> (une belle teinte de bleu clair) devient en RGB 565 <code>(8/31, 34/63, 30/31)</code>. C&#39;est quasiment indiscernable !</p><blockquote><p>Note : Les valeurs entre parenthèses représentent les valeurs entières pour chaque composante de couleur (Rouge, Vert, Bleu).</p></blockquote><p>En RGB 888 : <img src="`+o+'" alt="checkerboard"></p><p>En RGB 565 : <img src="'+p+`" alt="checkerboard"></p><h2 id="encodage-binaire" tabindex="-1">Encodage binaire <a class="header-anchor" href="#encodage-binaire" aria-label="Permalink to &quot;Encodage binaire&quot;">​</a></h2><p>L&#39;encodage binaire d&#39;une couleur en RGB 565 se fait en concaténant les bits de chaque couleur dans l&#39;ordre suivant : Rouge (5 bits), Vert (6 bits), Bleu (5 bits).</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span>RED    GREEN   BLUE</span></span>
<span class="line"><span>01000  100010  11110</span></span>
<span class="line"><span>=8     =34     =30</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Donc chaque pixel rentre parfaitement dans un entier non signé sur 16 bits (<code>u16</code>).</p><p>Voir le <a href="./schemas/eif1-format-v3.jpg">Schéma sur le fonctionnement du format de fichier EIF1</a> pour une représentation visuelle plus claire.</p><p>Sinon, voici un petit site web sympa pour sélectionner et visualiser des couleurs en RGB 565 : <a href="https://rgbcolorpicker.com/565" target="_blank" rel="noreferrer">https://rgbcolorpicker.com/565</a></p><h2 id="conversion" tabindex="-1">Conversion <a class="header-anchor" href="#conversion" aria-label="Permalink to &quot;Conversion&quot;">​</a></h2><h3 id="rgb-888-rgb-565" tabindex="-1">RGB 888 -&gt; RGB 565 <a class="header-anchor" href="#rgb-888-rgb-565" aria-label="Permalink to &quot;RGB 888 -&gt; RGB 565&quot;">​</a></h3><p>Pour convertir une couleur du format RGB 888 au format RGB 565, c&#39;est assez simple. Il suffit de réduire les 8 bits en 5 ou 6 bits selon la couleur. On va devoir couper les bits de poids faible (les bits les moins significatifs (<strong>à droite</strong>)), en gros, on retire de la précision.</p><p>Exemple en Rust :</p><div class="language-rs line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">rs</span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span style="color:#569CD6;">fn</span><span style="color:#DCDCAA;"> rgb888_to_rgb565</span><span style="color:#D4D4D4;">(</span><span style="color:#9CDCFE;">r</span><span style="color:#D4D4D4;">: </span><span style="color:#4EC9B0;">u8</span><span style="color:#D4D4D4;">, </span><span style="color:#9CDCFE;">g</span><span style="color:#D4D4D4;">: </span><span style="color:#4EC9B0;">u8</span><span style="color:#D4D4D4;">, </span><span style="color:#9CDCFE;">b</span><span style="color:#D4D4D4;">: </span><span style="color:#4EC9B0;">u8</span><span style="color:#D4D4D4;">) -&gt; </span><span style="color:#4EC9B0;">u16</span><span style="color:#D4D4D4;"> {</span></span>
<span class="line"><span style="color:#569CD6;">    let</span><span style="color:#9CDCFE;"> r5</span><span style="color:#D4D4D4;"> = (</span><span style="color:#9CDCFE;">r</span><span style="color:#D4D4D4;"> &gt;&gt; </span><span style="color:#B5CEA8;">3</span><span style="color:#D4D4D4;">) </span><span style="color:#569CD6;">as</span><span style="color:#4EC9B0;"> u16</span><span style="color:#D4D4D4;">; </span><span style="color:#6A9955;">// Prendre les 5 bits de poids fort du rouge</span></span>
<span class="line"><span style="color:#569CD6;">    let</span><span style="color:#9CDCFE;"> g6</span><span style="color:#D4D4D4;"> = (</span><span style="color:#9CDCFE;">g</span><span style="color:#D4D4D4;"> &gt;&gt; </span><span style="color:#B5CEA8;">2</span><span style="color:#D4D4D4;">) </span><span style="color:#569CD6;">as</span><span style="color:#4EC9B0;"> u16</span><span style="color:#D4D4D4;">; </span><span style="color:#6A9955;">// Prendre les 6 bits de poids fort du vert</span></span>
<span class="line"><span style="color:#569CD6;">    let</span><span style="color:#9CDCFE;"> b5</span><span style="color:#D4D4D4;"> = (</span><span style="color:#9CDCFE;">b</span><span style="color:#D4D4D4;"> &gt;&gt; </span><span style="color:#B5CEA8;">3</span><span style="color:#D4D4D4;">) </span><span style="color:#569CD6;">as</span><span style="color:#4EC9B0;"> u16</span><span style="color:#D4D4D4;">; </span><span style="color:#6A9955;">// Prendre les 5 bits de poids fort du bleu</span></span>
<span class="line"></span>
<span class="line"><span style="color:#D4D4D4;">    (</span><span style="color:#9CDCFE;">r5</span><span style="color:#D4D4D4;"> &lt;&lt; </span><span style="color:#B5CEA8;">11</span><span style="color:#D4D4D4;">) | (</span><span style="color:#9CDCFE;">g6</span><span style="color:#D4D4D4;"> &lt;&lt; </span><span style="color:#B5CEA8;">5</span><span style="color:#D4D4D4;">) | </span><span style="color:#9CDCFE;">b5</span><span style="color:#6A9955;"> // Combiner les bits dans un seul entier u16</span></span>
<span class="line"><span style="color:#D4D4D4;">}</span></span>
<span class="line"><span style="color:#6A9955;">// rgb888_to_rgb565(66, 138, 245) =&gt; 0b01000_100010_11110 = 0x442E</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>On renvoie un entier non signé sur 16 bits (<code>u16</code>) représentant la couleur en RGB 565. Et non directement les 3 composantes séparées, car tout simplement, ça sert à stocker la couleur dans un seul u16, plutôt que dans 3 u8 séparés.</p><p>Et un petit exemple en Python (pour les amateurs de Python) :</p><div class="language-py line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">py</span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span style="color:#569CD6;">def</span><span style="color:#DCDCAA;"> rgb888_to_rgb565</span><span style="color:#D4D4D4;">(</span><span style="color:#9CDCFE;">r</span><span style="color:#D4D4D4;">, </span><span style="color:#9CDCFE;">g</span><span style="color:#D4D4D4;">, </span><span style="color:#9CDCFE;">b</span><span style="color:#D4D4D4;">):</span></span>
<span class="line"><span style="color:#D4D4D4;">    r5 = r &gt;&gt; </span><span style="color:#B5CEA8;">3</span><span style="color:#6A9955;">  # Prendre les 5 bits de poids fort du rouge</span></span>
<span class="line"><span style="color:#D4D4D4;">    g6 = g &gt;&gt; </span><span style="color:#B5CEA8;">2</span><span style="color:#6A9955;">  # Prendre les 6 bits de poids fort du vert</span></span>
<span class="line"><span style="color:#D4D4D4;">    b5 = b &gt;&gt; </span><span style="color:#B5CEA8;">3</span><span style="color:#6A9955;">  # Prendre les 5 bits de poids fort du bleu</span></span>
<span class="line"><span style="color:#C586C0;">    return</span><span style="color:#D4D4D4;"> (r5 &lt;&lt; </span><span style="color:#B5CEA8;">11</span><span style="color:#D4D4D4;">) | (g6 &lt;&lt; </span><span style="color:#B5CEA8;">5</span><span style="color:#D4D4D4;">) | b5  </span><span style="color:#6A9955;"># Combiner les bits dans un seul entier u16</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A9955;"># rgb888_to_rgb565(66, 138, 245) =&gt; 0b01000_100010_11110 = 0x442E</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>Oui, Python permet aussi de faire des opérations bit à bit, ce n&#39;est pas que du scripting ! (Surprenant hein ?)</p><h3 id="rgb-565-rgb-888" tabindex="-1">RGB 565 -&gt; RGB 888 <a class="header-anchor" href="#rgb-565-rgb-888" aria-label="Permalink to &quot;RGB 565 -&gt; RGB 888&quot;">​</a></h3><p>On est sur le principe inverse. On va devoir étendre les 5 ou 6 bits en 8 bits. On rajoute des bits de poids faible (les bits les moins significatifs (<strong>à droite</strong>)). En gros, des zéros.</p><p>Exemple en Rust :</p><div class="language-rs line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">rs</span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span style="color:#569CD6;">fn</span><span style="color:#DCDCAA;"> rgb565_to_rgb888</span><span style="color:#D4D4D4;">(</span><span style="color:#9CDCFE;">rgb565</span><span style="color:#D4D4D4;">: </span><span style="color:#4EC9B0;">u16</span><span style="color:#D4D4D4;">) -&gt; (</span><span style="color:#4EC9B0;">u8</span><span style="color:#D4D4D4;">, </span><span style="color:#4EC9B0;">u8</span><span style="color:#D4D4D4;">, </span><span style="color:#4EC9B0;">u8</span><span style="color:#D4D4D4;">) {</span></span>
<span class="line"><span style="color:#569CD6;">    let</span><span style="color:#9CDCFE;"> r5</span><span style="color:#D4D4D4;"> = (</span><span style="color:#9CDCFE;">rgb565</span><span style="color:#D4D4D4;"> &gt;&gt; </span><span style="color:#B5CEA8;">11</span><span style="color:#D4D4D4;">) &amp; </span><span style="color:#B5CEA8;">0x1F</span><span style="color:#D4D4D4;">; </span><span style="color:#6A9955;">// Extraire les 5 bits du rouge</span></span>
<span class="line"><span style="color:#569CD6;">    let</span><span style="color:#9CDCFE;"> g6</span><span style="color:#D4D4D4;"> = (</span><span style="color:#9CDCFE;">rgb565</span><span style="color:#D4D4D4;"> &gt;&gt; </span><span style="color:#B5CEA8;">5</span><span style="color:#D4D4D4;">) &amp; </span><span style="color:#B5CEA8;">0x3F</span><span style="color:#D4D4D4;">;  </span><span style="color:#6A9955;">// Extraire les 6 bits du vert</span></span>
<span class="line"><span style="color:#569CD6;">    let</span><span style="color:#9CDCFE;"> b5</span><span style="color:#D4D4D4;"> = </span><span style="color:#9CDCFE;">rgb565</span><span style="color:#D4D4D4;"> &amp; </span><span style="color:#B5CEA8;">0x1F</span><span style="color:#D4D4D4;">;         </span><span style="color:#6A9955;">// Extraire les 5 bits du bleu</span></span>
<span class="line"></span>
<span class="line"><span style="color:#569CD6;">    let</span><span style="color:#9CDCFE;"> r8</span><span style="color:#D4D4D4;"> = (</span><span style="color:#9CDCFE;">r5</span><span style="color:#D4D4D4;"> &lt;&lt; </span><span style="color:#B5CEA8;">3</span><span style="color:#D4D4D4;">) | (</span><span style="color:#9CDCFE;">r5</span><span style="color:#D4D4D4;"> &gt;&gt; </span><span style="color:#B5CEA8;">2</span><span style="color:#D4D4D4;">); </span><span style="color:#6A9955;">// Étendre à 8 bits</span></span>
<span class="line"><span style="color:#569CD6;">    let</span><span style="color:#9CDCFE;"> g8</span><span style="color:#D4D4D4;"> = (</span><span style="color:#9CDCFE;">g6</span><span style="color:#D4D4D4;"> &lt;&lt; </span><span style="color:#B5CEA8;">2</span><span style="color:#D4D4D4;">) | (</span><span style="color:#9CDCFE;">g6</span><span style="color:#D4D4D4;"> &gt;&gt; </span><span style="color:#B5CEA8;">4</span><span style="color:#D4D4D4;">); </span><span style="color:#6A9955;">// Étendre à 8 bits</span></span>
<span class="line"><span style="color:#569CD6;">    let</span><span style="color:#9CDCFE;"> b8</span><span style="color:#D4D4D4;"> = (</span><span style="color:#9CDCFE;">b5</span><span style="color:#D4D4D4;"> &lt;&lt; </span><span style="color:#B5CEA8;">3</span><span style="color:#D4D4D4;">) | (</span><span style="color:#9CDCFE;">b5</span><span style="color:#D4D4D4;"> &gt;&gt; </span><span style="color:#B5CEA8;">2</span><span style="color:#D4D4D4;">); </span><span style="color:#6A9955;">// Étendre à 8 bits</span></span>
<span class="line"></span>
<span class="line"><span style="color:#D4D4D4;">    (</span><span style="color:#9CDCFE;">r8</span><span style="color:#569CD6;"> as</span><span style="color:#4EC9B0;"> u8</span><span style="color:#D4D4D4;">, </span><span style="color:#9CDCFE;">g8</span><span style="color:#569CD6;"> as</span><span style="color:#4EC9B0;"> u8</span><span style="color:#D4D4D4;">, </span><span style="color:#9CDCFE;">b8</span><span style="color:#569CD6;"> as</span><span style="color:#4EC9B0;"> u8</span><span style="color:#D4D4D4;">)</span></span>
<span class="line"><span style="color:#D4D4D4;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>On renvoie un tuple de 3 entiers non signés sur 8 bits (<code>u8</code>) représentant les composantes Rouge, Vert et Bleu en RGB 888. Oui, là on a le droit de renvoyer les 3 composantes séparées 🤨.</p><p>Et à nouveau un petit exemple en Python :</p><div class="language-py line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">py</span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span style="color:#569CD6;">def</span><span style="color:#DCDCAA;"> rgb565_to_rgb888</span><span style="color:#D4D4D4;">(</span><span style="color:#9CDCFE;">rgb565</span><span style="color:#D4D4D4;">):</span></span>
<span class="line"><span style="color:#D4D4D4;">    r5 = (rgb565 &gt;&gt; </span><span style="color:#B5CEA8;">11</span><span style="color:#D4D4D4;">) &amp; </span><span style="color:#569CD6;">0x</span><span style="color:#B5CEA8;">1F</span><span style="color:#6A9955;">  # Extraire les 5 bits du rouge</span></span>
<span class="line"><span style="color:#D4D4D4;">    g6 = (rgb565 &gt;&gt; </span><span style="color:#B5CEA8;">5</span><span style="color:#D4D4D4;">) &amp; </span><span style="color:#569CD6;">0x</span><span style="color:#B5CEA8;">3F</span><span style="color:#6A9955;">   # Extraire les 6 bits du vert</span></span>
<span class="line"><span style="color:#D4D4D4;">    b5 = rgb565 &amp; </span><span style="color:#569CD6;">0x</span><span style="color:#B5CEA8;">1F</span><span style="color:#6A9955;">          # Extraire les 5 bits du bleu</span></span>
<span class="line"></span>
<span class="line"><span style="color:#D4D4D4;">    r8 = (r5 &lt;&lt; </span><span style="color:#B5CEA8;">3</span><span style="color:#D4D4D4;">) | (r5 &gt;&gt; </span><span style="color:#B5CEA8;">2</span><span style="color:#D4D4D4;">)  </span><span style="color:#6A9955;"># Étendre à 8 bits</span></span>
<span class="line"><span style="color:#D4D4D4;">    g8 = (g6 &lt;&lt; </span><span style="color:#B5CEA8;">2</span><span style="color:#D4D4D4;">) | (g6 &gt;&gt; </span><span style="color:#B5CEA8;">4</span><span style="color:#D4D4D4;">)  </span><span style="color:#6A9955;"># Étendre à 8 bits</span></span>
<span class="line"><span style="color:#D4D4D4;">    b8 = (b5 &lt;&lt; </span><span style="color:#B5CEA8;">3</span><span style="color:#D4D4D4;">) | (b5 &gt;&gt; </span><span style="color:#B5CEA8;">2</span><span style="color:#D4D4D4;">)  </span><span style="color:#6A9955;"># Étendre à 8 bits</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C586C0;">    return</span><span style="color:#D4D4D4;"> (r8, g8, b8)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A9955;"># rgb565_to_rgb888(0x442E) =&gt; (66, 136, 248)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><h2 id="ressources-supplementaires" tabindex="-1">Ressources supplémentaires <a class="header-anchor" href="#ressources-supplementaires" aria-label="Permalink to &quot;Ressources supplémentaires&quot;">​</a></h2><p>Si vous voulez en savoir plus sur le RGB 565, voici quelques ressources intéressantes :</p><ul><li><a href="https://en.wikipedia.org/wiki/RGB_color_space#RGB_565" target="_blank" rel="noreferrer">Wikipedia - RGB565</a></li><li><a href="https://stackoverflow.com/questions/16452383/rgb565-color-conversion" target="_blank" rel="noreferrer">RGB565 Color Conversion - Stack Overflow</a></li></ul><p>Tutoriel sur les opérations bit à bit en Rust : <a href="https://www.youtube.com/watch?v=qYTQ1hUlva4" target="_blank" rel="noreferrer">Rust Programming Tutorial #31 - bitwise operators</a></p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>RGB 888 : 24 bits par pixel (3 octets), un octet par couleur, 16 millions de couleurs.</li><li>RGB 565 : 16 bits par pixel (2 octets), 5 bits pour le rouge, 6 bits pour le vert, 5 bits pour le bleu, 65 mille couleurs.</li><li>Idéal pour les systèmes embarqués avec peu de mémoire, comme la calculatrice Numworks.</li></ul><p>Conversion :</p><ul><li>RGB 888 -&gt; 565 : Décaler les bits de poids faible (droite) et combiner sur un u16.</li><li>RGB 565 -&gt; 888 : Extraire les bits et étendre en ajoutant des bits de poids faible (droite).</li></ul>`,60)])])}const m=n(r,[["render",t]]);export{y as __pageData,m as default};
